mapper.update:
UPDATE chat_participant
SET last_read_message_id = #{lastReadMessageId}
WHERE chat_id = #{chatId}
  AND user_id = #{userId}

UPDATE chat_participant
SET left_at = NOW()
WHERE chat_id = #{chatId}
  AND user_id = #{userId}

UPDATE chat_participant
SET left_at = NULL,
    is_alarm = TRUE
WHERE chat_id = #{chatId}
  AND user_id = #{userId}

mapper.select:
SELECT participant_id, chat_id, user_id, last_read_message_id, is_alarm, left_at
FROM chat_participant
WHERE chat_id = #{chatId}
  AND user_id = #{userId}
  AND left_at IS NULL

SELECT participant_id, chat_id, user_id, last_read_message_id, is_alarm, left_at
FROM chat_participant
WHERE chat_id = #{chatId}
  AND user_id = #{userId}
